"""Open-ended, composable tool-action interface.

Environments publish **tool schemas at run time** (``ToolSpec``); nothing about a particular environment, website
or business strategy is compiled into CAM. A tool is a primitive capability (``click``, ``fill``, an AppWorld API
such as ``spotify.show_playlist``) with typed arguments:

* ``element`` — a reference to one element of the current observation (pointer, optionally restricted by role);
* ``enum``    — one of a fixed, schema-supplied list of values (e.g. a key name);
* ``text``    — free text, generated by the frozen LLM under CAM's control vectors;
* ``json``    — a JSON object validated against a JSON schema (generated by the frozen LLM under CAM's control).

CAM's action is factorised as: structured candidate (tool, element, enum value) chosen by CAM's own pointer
network, then — if the tool has a text/json argument — a token sequence sampled from the frozen LLM conditioned on
CAM's control vectors. Every call is validated against its schema before execution (invalid calls are counted and
never reach the environment).

Safety: each tool declares ``effect`` (``read`` | ``sandboxed`` | ``external``). ``ToolGate`` refuses ``external``
tools unless an explicit approval names them; autonomous training only ever runs environments whose tools are
``read``/``sandboxed`` (local MiniWoB pages, AppWorld's simulated databases).
"""
from __future__ import annotations

import json
from dataclasses import asdict, dataclass, field
from typing import Any, Optional

ARG_TYPES = ("element", "enum", "text", "json")
EFFECTS = ("read", "sandboxed", "external")


@dataclass(frozen=True)
class ArgSpec:
    name: str
    type: str
    description: str = ""
    required: bool = True
    roles: tuple = ()               # element: allowed roles (empty = any targetable element)
    options: tuple = ()             # enum: allowed values
    json_schema: Optional[str] = None  # json: JSON-schema (serialised, so the spec stays hashable)

    def __post_init__(self):
        if self.type not in ARG_TYPES:
            raise ValueError(f"unknown argument type {self.type!r} for {self.name!r}")
        if self.type == "enum" and not self.options:
            raise ValueError(f"enum argument {self.name!r} needs options")


@dataclass(frozen=True)
class ToolSpec:
    name: str
    description: str
    args: tuple = ()
    effect: str = "sandboxed"

    def __post_init__(self):
        if self.effect not in EFFECTS:
            raise ValueError(f"unknown effect {self.effect!r}")
        kinds = [a.type for a in self.args]
        # CAM's factorisation: at most one argument of each structured kind and one generated argument
        if kinds.count("element") > 1 or kinds.count("enum") > 1 or (kinds.count("text") + kinds.count("json")) > 1:
            raise ValueError(f"tool {self.name!r}: at most one element, one enum and one text/json argument")

    @property
    def element_arg(self) -> Optional[ArgSpec]:
        return next((a for a in self.args if a.type == "element"), None)

    @property
    def enum_arg(self) -> Optional[ArgSpec]:
        return next((a for a in self.args if a.type == "enum"), None)

    @property
    def gen_arg(self) -> Optional[ArgSpec]:
        return next((a for a in self.args if a.type in ("text", "json")), None)

    def doc(self) -> str:
        """Natural-language documentation (what the frozen LLM encodes as the tool's semantic embedding)."""
        parts = []
        for a in self.args:
            extra = ""
            if a.type == "element" and a.roles:
                extra = f" (one of: {', '.join(a.roles)})"
            if a.type == "enum":
                extra = f" (one of: {', '.join(map(str, a.options))})"
            parts.append(f"{a.name}: {a.type}{extra}{' - ' + a.description if a.description else ''}")
        return f"tool {self.name}: {self.description}" + (f" | arguments: {'; '.join(parts)}" if parts else "")

    def to_dict(self) -> dict:
        return asdict(self)


@dataclass
class Element:
    eid: str                    # the environment's own reference (BrowserGym bid, JSON path, ...)
    role: str
    text: str                   # what the agent sees (encoded by the frozen LLM); never contains hidden state
    depth: int = 0
    targetable: bool = True
    parent: Optional[str] = None


@dataclass
class Observation:
    goal: str
    elements: list = field(default_factory=list)
    text: str = ""              # free-form feedback (last error / last tool output summary)
    step: int = 0
    done: bool = False


@dataclass
class ToolCall:
    tool: str
    element: Optional[str] = None     # element eid
    enum: Optional[str] = None
    text: Optional[str] = None        # generated text / json string

    def render(self, tools: dict) -> str:
        spec = tools.get(self.tool)
        args = []
        if spec is not None:
            for a in spec.args:
                v = {"element": self.element, "enum": self.enum}.get(a.type, self.text)
                if v is not None:
                    args.append(f"{a.name}={v!r}")
        return f"{self.tool}({', '.join(args)})"


@dataclass
class Candidate:
    """The structured part of an action: tool + optional element + optional enum value."""
    tool: int                   # index into the step's tool list
    element: int = -1           # index into the observation's element list (-1 = none)
    enum: Optional[str] = None


def element_ok(spec: ToolSpec, el: Element) -> bool:
    a = spec.element_arg
    if a is None or not el.targetable:
        return False
    return not a.roles or el.role in a.roles


def enumerate_candidates(tools: list, obs: Observation, max_candidates: int = 512) -> list:
    """All schema-valid structured candidates for this observation (the action mask, made explicit)."""
    out = []
    for ti, spec in enumerate(tools):
        els = [i for i, e in enumerate(obs.elements) if element_ok(spec, e)] if spec.element_arg else [-1]
        if spec.element_arg and not els:
            continue
        enums = list(spec.enum_arg.options) if spec.enum_arg else [None]
        for ei in els:
            for ev in enums:
                out.append(Candidate(ti, ei, ev))
    return out[:max_candidates]


def _type_ok(v: Any, t: Any) -> bool:
    if t is None:
        return True
    ts = t if isinstance(t, list) else [t]
    for tt in ts:
        if (tt == "string" and isinstance(v, str)) or (tt == "integer" and isinstance(v, int) and not isinstance(v, bool)) \
                or (tt == "number" and isinstance(v, (int, float)) and not isinstance(v, bool)) \
                or (tt == "boolean" and isinstance(v, bool)) or (tt == "array" and isinstance(v, list)) \
                or (tt == "object" and isinstance(v, dict)) or (tt == "null" and v is None):
            return True
    return False


def validate_json_args(text: str, schema: Optional[str]) -> tuple[Optional[dict], Optional[str]]:
    """Parse and validate generated JSON arguments against a (subset of) JSON schema: object, required keys,
    known properties, primitive types, enums. Returns (args, error)."""
    try:
        s = text.strip()
        if s.startswith("```"):
            s = s.strip("`").split("\n", 1)[-1]
        if not s.startswith("{"):
            i = s.find("{")
            s = s[i:] if i >= 0 else s
        j = s.rfind("}")
        if j >= 0:
            s = s[: j + 1]
        args = json.loads(s) if s else {}
    except Exception as e:  # noqa: BLE001
        return None, f"invalid JSON: {e}"
    if not isinstance(args, dict):
        return None, "arguments must be a JSON object"
    if not schema:
        return args, None
    sc = json.loads(schema)
    props = sc.get("properties", {})
    for r in sc.get("required", []):
        if r not in args:
            return None, f"missing required argument {r!r}"
    for k, v in args.items():
        if k not in props:
            return None, f"unknown argument {k!r}"
        p = props[k]
        if not _type_ok(v, p.get("type")):
            return None, f"argument {k!r} has the wrong type (expected {p.get('type')})"
        if "enum" in p and v not in p["enum"]:
            return None, f"argument {k!r} must be one of {p['enum']}"
    return args, None


def validate_call(call: ToolCall, tools: dict, obs: Observation) -> Optional[str]:
    """None if the call satisfies its tool's schema in this observation, else an error message."""
    spec = tools.get(call.tool)
    if spec is None:
        return f"unknown tool {call.tool!r}"
    ea = spec.element_arg
    if ea is not None:
        el = next((e for e in obs.elements if e.eid == call.element), None)
        if el is None:
            return f"element {call.element!r} is not in the observation"
        if not element_ok(spec, el):
            return f"element {call.element!r} ({el.role}) is not a valid target for {spec.name}"
    if spec.enum_arg is not None and call.enum not in spec.enum_arg.options:
        return f"{call.enum!r} is not an allowed value for {spec.enum_arg.name}"
    ga = spec.gen_arg
    if ga is not None:
        if call.text is None:
            return f"missing {ga.name}"
        if ga.type == "json":
            _, err = validate_json_args(call.text, ga.json_schema)
            if err:
                return err
        if ga.type == "text" and len(call.text) > 2000:
            return "text argument too long"
    return None


class ToolGate:
    """Refuses tools with external side effects unless explicitly approved (training never approves any)."""

    def __init__(self, approved_external: tuple = ()):
        self.approved = set(approved_external)

    def check(self, spec: ToolSpec) -> None:
        if spec.effect == "external" and spec.name not in self.approved:
            raise PermissionError(f"tool {spec.name!r} has external side effects and is not approved")
